/**
 * Draft queue persistence.
 *
 * Drafts are generated by the agent but never sent until the user taps Send.
 * A pending draft is unique per thread: regenerating replaces the old pending
 * row while keeping sent/discarded rows as history. Dismissals are also stored
 * so the thread card does not reappear after the user says No.
 *
 * Voice samples are the last few replies the user approved. They are fed back
 * into the drafting prompt, which is the simplest on-device "learn your voice"
 * loop that does not require a second model or a training job.
 */
import { useCallback, useEffect, useState } from 'react';
import * as SQLite from 'expo-sqlite';

const DB_NAME = 'threadmymail.db';
const MAX_VOICE_SAMPLES = 5;

export type DraftStatus = 'pending' | 'sent' | 'discarded';

export type Draft = {
  id: string;
  threadId: string;
  messageId: string | null;
  to: string;
  subject: string;
  body: string;
  status: DraftStatus;
  createdAt: number;
  updatedAt: number;
};

let dbPromise: Promise<SQLite.SQLiteDatabase> | null = null;

function openDb(): Promise<SQLite.SQLiteDatabase> {
  if (!dbPromise) {
    dbPromise = SQLite.openDatabaseAsync(DB_NAME).then(async (db) => {
      await db.execAsync(`
        PRAGMA journal_mode = WAL;
        CREATE TABLE IF NOT EXISTS agent_drafts (
          id TEXT PRIMARY KEY NOT NULL,
          thread_id TEXT NOT NULL,
          message_id TEXT,
          to_address TEXT NOT NULL,
          subject TEXT NOT NULL,
          body TEXT NOT NULL,
          status TEXT NOT NULL,
          created_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_drafts_status ON agent_drafts(status, created_at DESC);
        CREATE INDEX IF NOT EXISTS idx_drafts_thread ON agent_drafts(thread_id, status);
        CREATE TABLE IF NOT EXISTS draft_dismissals (
          thread_id TEXT PRIMARY KEY NOT NULL,
          created_at INTEGER NOT NULL
        );
        CREATE TABLE IF NOT EXISTS voice_samples (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          text TEXT NOT NULL,
          created_at INTEGER NOT NULL
        );
      `);
      return db;
    });
  }
  return dbPromise;
}

function fromRow(row: Record<string, unknown>): Draft {
  return {
    id: String(row.id),
    threadId: String(row.thread_id),
    messageId: row.message_id ? String(row.message_id) : null,
    to: String(row.to_address),
    subject: String(row.subject),
    body: String(row.body),
    status: String(row.status) as DraftStatus,
    createdAt: Number(row.created_at),
    updatedAt: Number(row.updated_at),
  };
}

const listeners = new Set<() => void>();

function notify(): void {
  listeners.forEach((listener) => listener());
}

export function subscribeDrafts(listener: () => void): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

function newDraftId(): string {
  return `draft_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
}

export async function createDraft(input: {
  threadId: string;
  messageId?: string | null;
  to: string;
  subject: string;
  body: string;
}): Promise<Draft> {
  const db = await openDb();
  const now = Date.now();
  const draft: Draft = {
    id: newDraftId(),
    threadId: input.threadId,
    messageId: input.messageId ?? null,
    to: input.to,
    subject: input.subject,
    body: input.body,
    status: 'pending',
    createdAt: now,
    updatedAt: now,
  };
  await db.withTransactionAsync(async () => {
    await db.runAsync(
      `UPDATE agent_drafts SET status = 'discarded', updated_at = $now
       WHERE thread_id = $thread_id AND status = 'pending'`,
      { $now: now, $thread_id: input.threadId },
    );
    await db.runAsync(
      `INSERT INTO agent_drafts (
         id, thread_id, message_id, to_address, subject, body, status, created_at, updated_at
       ) VALUES ($id, $thread_id, $message_id, $to, $subject, $body, 'pending', $created_at, $updated_at)`,
      {
        $id: draft.id,
        $thread_id: draft.threadId,
        $message_id: draft.messageId,
        $to: draft.to,
        $subject: draft.subject,
        $body: draft.body,
        $created_at: draft.createdAt,
        $updated_at: draft.updatedAt,
      },
    );
  });
  notify();
  return draft;
}

export async function getDraft(id: string): Promise<Draft | null> {
  const db = await openDb();
  const row = await db.getFirstAsync<Record<string, unknown>>(
    'SELECT * FROM agent_drafts WHERE id = $id',
    { $id: id },
  );
  return row ? fromRow(row) : null;
}

export async function loadPendingDrafts(): Promise<Draft[]> {
  const db = await openDb();
  const rows = await db.getAllAsync<Record<string, unknown>>(
    `SELECT * FROM agent_drafts WHERE status = 'pending' ORDER BY created_at DESC`,
  );
  return rows.map(fromRow);
}

export async function loadPendingDraftForThread(threadId: string): Promise<Draft | null> {
  const db = await openDb();
  const row = await db.getFirstAsync<Record<string, unknown>>(
    `SELECT * FROM agent_drafts
     WHERE thread_id = $thread_id AND status = 'pending'
     ORDER BY created_at DESC LIMIT 1`,
    { $thread_id: threadId },
  );
  return row ? fromRow(row) : null;
}

/** Most recent sent-draft time per thread, used to spot waiting-on-them threads. */
export async function loadLastSentDraftTimes(): Promise<Map<string, number>> {
  const db = await openDb();
  const rows = await db.getAllAsync<{ thread_id: string; last_sent: number }>(
    `SELECT thread_id, MAX(updated_at) AS last_sent FROM agent_drafts
     WHERE status = 'sent' GROUP BY thread_id`,
  );
  return new Map(rows.map((row) => [row.thread_id, Number(row.last_sent)]));
}

export async function countPendingDrafts(): Promise<number> {
  const db = await openDb();
  const row = await db.getFirstAsync<{ n: number }>(
    `SELECT COUNT(*) AS n FROM agent_drafts WHERE status = 'pending'`,
  );
  return row?.n ?? 0;
}

export async function setDraftStatus(id: string, status: DraftStatus): Promise<void> {
  const db = await openDb();
  await db.runAsync(
    'UPDATE agent_drafts SET status = $status, updated_at = $updated_at WHERE id = $id',
    { $status: status, $updated_at: Date.now(), $id: id },
  );
  notify();
}

export async function dismissDraftPrompt(threadId: string): Promise<void> {
  const db = await openDb();
  await db.runAsync(
    `INSERT INTO draft_dismissals (thread_id, created_at) VALUES ($thread_id, $created_at)
     ON CONFLICT(thread_id) DO NOTHING`,
    { $thread_id: threadId, $created_at: Date.now() },
  );
  notify();
}

export async function isDraftPromptDismissed(threadId: string): Promise<boolean> {
  const db = await openDb();
  const row = await db.getFirstAsync<{ n: number }>(
    'SELECT COUNT(*) AS n FROM draft_dismissals WHERE thread_id = $thread_id',
    { $thread_id: threadId },
  );
  return (row?.n ?? 0) > 0;
}

export async function addVoiceSample(text: string): Promise<void> {
  const sample = text.trim();
  if (sample.length < 20) return;
  const db = await openDb();
  await db.runAsync(
    'INSERT INTO voice_samples (text, created_at) VALUES ($text, $created_at)',
    { $text: sample.slice(0, 4_000), $created_at: Date.now() },
  );
  await db.runAsync(
    `DELETE FROM voice_samples WHERE id NOT IN (
       SELECT id FROM voice_samples ORDER BY created_at DESC LIMIT $keep
     )`,
    { $keep: MAX_VOICE_SAMPLES },
  );
}

export async function loadVoiceSamples(limit = 3): Promise<string[]> {
  const db = await openDb();
  const rows = await db.getAllAsync<{ text: string }>(
    'SELECT text FROM voice_samples ORDER BY created_at DESC LIMIT $limit',
    { $limit: Math.max(0, Math.min(MAX_VOICE_SAMPLES, limit)) },
  );
  return rows.map((row) => row.text);
}

/** React binding for the queue; reloads on every draft mutation. */
export function usePendingDrafts(): Draft[] {
  const [drafts, setDrafts] = useState<Draft[]>([]);

  const reload = useCallback(() => {
    void loadPendingDrafts().then(setDrafts).catch(() => setDrafts([]));
  }, []);

  useEffect(() => {
    reload();
    return subscribeDrafts(reload);
  }, [reload]);

  return drafts;
}
